import type { Decimal } from '../shared/decimal.ts';

/**
 * Solicitud de préstamo ya tipada (value object inmutable).
 */
export class LoanRequest {
  readonly principal: Decimal;
  readonly termMonths: number;
  readonly creditScore: number;
  readonly customerAge: number;

  constructor(principal: Decimal, termMonths: number, creditScore: number, customerAge: number) {
    this.principal = principal;
    this.termMonths = termMonths;
    this.creditScore = creditScore;
    this.customerAge = customerAge;
  }
}

import { Decimal } from '../shared/decimal.ts';

export type LoanStatus = 'APPROVED' | 'REJECTED';
export type RejectionCode = 'E01' | 'E02' | 'E03' | 'E04';

export interface ApprovedAmounts {
  readonly annualRate: Decimal;
  readonly monthlyPayment: Decimal;
  readonly insurance: Decimal;
  readonly totalInterest: Decimal;
  readonly totalPaid: Decimal;
}

/**
 * Resultado de la evaluación. En rechazo, tasa e importes quedan en cero.
 */
export class LoanOutcome {
  readonly status: LoanStatus;
  readonly errorCode: string;
  readonly annualRate: Decimal;
  readonly monthlyPayment: Decimal;
  readonly insurance: Decimal;
  readonly totalInterest: Decimal;
  readonly totalPaid: Decimal;

  private constructor(status: LoanStatus, errorCode: string, amounts: ApprovedAmounts) {
    this.status = status;
    this.errorCode = errorCode;
    this.annualRate = amounts.annualRate;
    this.monthlyPayment = amounts.monthlyPayment;
    this.insurance = amounts.insurance;
    this.totalInterest = amounts.totalInterest;
    this.totalPaid = amounts.totalPaid;
  }

  /**
   * @rule R-014
   */
  static approved(amounts: ApprovedAmounts): LoanOutcome {
    return new LoanOutcome('APPROVED', '', amounts);
  }

  /**
   * Rechazo con valores por defecto en cero.
   * @rule R-014
   */
  static rejected(code: RejectionCode): LoanOutcome {
    const zeros: ApprovedAmounts = {
      annualRate: Decimal.of('0.0000'),
      monthlyPayment: Decimal.of('0.00'),
      insurance: Decimal.of('0.00'),
      totalInterest: Decimal.of('0.00'),
      totalPaid: Decimal.of('0.00'),
    };
    return new LoanOutcome('REJECTED', code, zeros);
  }
}

import type { LoanRequest } from '../LoanRequest.ts';
import type { RejectionCode } from '../LoanOutcome.ts';

/**
 * Specification de rechazo: devuelve el código de error o null si la solicitud cumple.
 */
export interface RejectionRule {
  evaluate(request: LoanRequest): RejectionCode | null;
}

import { Decimal } from '../../shared/decimal.ts';
import type { LoanRequest } from '../LoanRequest.ts';
import type { RejectionCode } from '../LoanOutcome.ts';
import type { RejectionRule } from './RejectionRule.ts';

const MIN_PRINCIPAL = Decimal.of('1000.00');
const MAX_PRINCIPAL = Decimal.of('500000.00');

export class AmountRangeRule implements RejectionRule {
  /**
   * Monto fuera de [1000.00, 500000.00] se rechaza con E01 (límites inclusivos).
   * @rule R-001
   */
  evaluate(request: LoanRequest): RejectionCode | null {
    const outOfRange = request.principal.lt(MIN_PRINCIPAL) || request.principal.gt(MAX_PRINCIPAL);
    return outOfRange ? 'E01' : null;
  }
}

import type { LoanRequest } from '../LoanRequest.ts';
import type { RejectionCode } from '../LoanOutcome.ts';
import type { RejectionRule } from './RejectionRule.ts';

const MIN_TERM_MONTHS = 6;
const MAX_TERM_MONTHS = 360;

export class TermRangeRule implements RejectionRule {
  /**
   * Plazo fuera de [6, 360] meses se rechaza con E02 (límites inclusivos).
   * @rule R-002
   */
  evaluate(request: LoanRequest): RejectionCode | null {
    const outOfRange = request.termMonths < MIN_TERM_MONTHS || request.termMonths > MAX_TERM_MONTHS;
    return outOfRange ? 'E02' : null;
  }
}

import { Decimal } from '../../shared/decimal.ts';
import type { LoanRequest } from '../LoanRequest.ts';
import type { RejectionCode } from '../LoanOutcome.ts';
import type { RejectionRule } from './RejectionRule.ts';

const MAX_MATURITY_AGE = 75;
const MONTHS_PER_YEAR = Decimal.of(12);

export class MaturityAgeRule implements RejectionRule {
  /**
   * Años completos del plazo: TRUNC(term_months / 12), sin redondeo.
   * @rule R-003
   */
  wholeTermYears(termMonths: number): number {
    return Decimal.of(termMonths).dividedBy(MONTHS_PER_YEAR, 0, 'DOWN').toInteger();
  }

  /**
   * Edad al vencimiento mayor a 75 se rechaza con E03.
   * @rule R-003
   */
  evaluate(request: LoanRequest): RejectionCode | null {
    const maturityAge = request.customerAge + this.wholeTermYears(request.termMonths);
    return maturityAge > MAX_MATURITY_AGE ? 'E03' : null;
  }
}

import type { LoanRequest } from '../LoanRequest.ts';
import type { RejectionCode } from '../LoanOutcome.ts';
import type { RejectionRule } from './RejectionRule.ts';
import type { BaseRateTable } from '../pricing/BaseRateTable.ts';

export class MinimumScoreRule implements RejectionRule {
  private readonly table: BaseRateTable;

  constructor(table: BaseRateTable) {
    this.table = table;
  }

  /**
   * Puntaje sin tasa base asignable (menor a 550) se rechaza con E04.
   * @rule R-004
   */
  evaluate(request: LoanRequest): RejectionCode | null {
    return this.table.baseRateFor(request.creditScore) === null ? 'E04' : null;
  }
}

import type { LoanRequest } from './LoanRequest.ts';
import type { RejectionCode } from './LoanOutcome.ts';
import type { RejectionRule } from './rules/RejectionRule.ts';

/**
 * Aplica las reglas de rechazo en orden y devuelve únicamente el primer error.
 */
export class EligibilityPolicy {
  private readonly orderedRules: readonly RejectionRule[];

  constructor(orderedRules: readonly RejectionRule[]) {
    this.orderedRules = orderedRules;
  }

  /**
   * Orden requerido: E01, E02, E03, E04; el primer rechazo detiene la evaluación.
   * @rule R-014
   * @rule R-001
   * @rule R-002
   * @rule R-003
   * @rule R-004
   */
  firstRejection(request: LoanRequest): RejectionCode | null {
    for (const rule of this.orderedRules) {
      const code = rule.evaluate(request);
      if (code !== null) {
        return code;
      }
    }
    return null;
  }
}

import { Decimal } from '../../shared/decimal.ts';

interface ScoreBand {
  readonly minScore: number;
  readonly annualRate: Decimal;
}

const BANDS: readonly ScoreBand[] = [
  { minScore: 750, annualRate: Decimal.of('0.0899') },
  { minScore: 650, annualRate: Decimal.of('0.1299') },
  { minScore: 550, annualRate: Decimal.of('0.1899') },
];

export class BaseRateTable {
  /**
   * Tasa anual base según puntaje; null si el puntaje es menor a 550.
   * @rule R-004
   */
  baseRateFor(creditScore: number): Decimal | null {
    for (const band of BANDS) {
      if (creditScore >= band.minScore) {
        return band.annualRate;
      }
    }
    return null;
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import type { LoanRequest } from '../LoanRequest.ts';

/**
 * Estrategia de ajuste de la tasa anual.
 */
export interface RateAdjustment {
  apply(annualRate: Decimal, request: LoanRequest): Decimal;
}

import { Decimal } from '../../shared/decimal.ts';
import type { LoanRequest } from '../LoanRequest.ts';
import type { RateAdjustment } from './RateAdjustment.ts';

const MIN_SCORE = 800;
const MAX_TERM_MONTHS = 60;
const DISCOUNT = Decimal.of('0.0025');

export class HighScoreShortTermPromotion implements RateAdjustment {
  /**
   * Puntaje >= 800 y plazo <= 60 meses: tasa - 0.0025.
   * @rule R-005
   */
  apply(annualRate: Decimal, request: LoanRequest): Decimal {
    const eligible = request.creditScore >= MIN_SCORE && request.termMonths <= MAX_TERM_MONTHS;
    return eligible ? annualRate.minus(DISCOUNT) : annualRate;
  }
}

import { Decimal } from '../../shared/decimal.ts';
import type { LoanRequest } from '../LoanRequest.ts';
import type { RateAdjustment } from './RateAdjustment.ts';

const LONG_TERM_MONTHS = 120;
const SURCHARGE = Decimal.of('0.0050');

export class LongTermSurcharge implements RateAdjustment {
  /**
   * Plazo > 120 meses: tasa + 0.0050.
   * @rule R-006
   */
  apply(annualRate: Decimal, request: LoanRequest): Decimal {
    return request.termMonths > LONG_TERM_MONTHS ? annualRate.plus(SURCHARGE) : annualRate;
  }
}

import { Decimal } from '../../shared/decimal.ts';
import type { LoanRequest } from '../LoanRequest.ts';
import type { BaseRateTable } from './BaseRateTable.ts';
import type { RateAdjustment } from './RateAdjustment.ts';

const RATE_SCALE = 4;

/**
 * Determina la tasa anual final: base por puntaje más ajustes.
 */
export class AnnualRateCalculator {
  private readonly table: BaseRateTable;
  private readonly adjustments: readonly RateAdjustment[];

  constructor(table: BaseRateTable, adjustments: readonly RateAdjustment[]) {
    this.table = table;
    this.adjustments = adjustments;
  }

  /**
   * Parte de la tasa base (R-004) y aplica promoción (R-005) y recargo (R-006).
   * Se invoca solo con solicitudes que pasaron la elegibilidad.
   * @rule R-004
   * @rule R-005
   * @rule R-006
   */
  calculate(request: LoanRequest): Decimal {
    const base = this.table.baseRateFor(request.creditScore) ?? Decimal.of('0.0000');
    let rate = base;
    for (const adjustment of this.adjustments) {
      rate = adjustment.apply(rate, request);
    }
    return rate.setScale(RATE_SCALE, 'HALF_UP');
  }
}

import { Decimal } from '../../shared/decimal.ts';

const ONE = Decimal.of(1);
const MONTHS_PER_YEAR = Decimal.of(12);
const RATE_SCALE = 9;
const MONEY_SCALE = 2;

/**
 * Cálculo de amortización francesa con las escalas intermedias del legacy.
 */
export class AmortizationCalculator {
  /**
   * Tasa mensual = ROUND_HALF_UP(tasa anual / 12, 9).
   * @rule R-007
   */
  monthlyRate(annualRate: Decimal): Decimal {
    return annualRate.dividedBy(MONTHS_PER_YEAR, RATE_SCALE, 'HALF_UP');
  }

  /**
   * Factor = ROUND_HALF_UP((1 + tasa mensual) ^ plazo, 9).
   * @rule R-008
   */
  capitalizationFactor(monthlyRate: Decimal, termMonths: number): Decimal {
    return ONE.plus(monthlyRate).pow(termMonths).setScale(RATE_SCALE, 'HALF_UP');
  }

  /**
   * Cuota = ROUND_HALF_UP(principal * tasa mensual * factor / (factor - 1), 2).
   * @rule R-009
   */
  monthlyPayment(principal: Decimal, monthlyRate: Decimal, factor: Decimal): Decimal {
    const numerator = principal.times(monthlyRate).times(factor);
    return numerator.dividedBy(factor.minus(ONE), MONEY_SCALE, 'HALF_UP');
  }
}

import { Decimal } from '../../shared/decimal.ts';

const MONEY_SCALE = 2;
const RATE_UNDER_40 = Decimal.of('0.00035');
const RATE_40_TO_59 = Decimal.of('0.00055');
const RATE_60_PLUS = Decimal.of('0.00095');

export class InsuranceCalculator {
  /**
   * Tasa de seguro: <40 => 0.00035; 40-59 => 0.00055; >=60 => 0.00095.
   * @rule R-010
   */
  rateForAge(customerAge: number): Decimal {
    if (customerAge < 40) {
      return RATE_UNDER_40;
    }
    return customerAge < 60 ? RATE_40_TO_59 : RATE_60_PLUS;
  }

  /**
   * Seguro mensual = ROUND_HALF_UP(principal * tasa de seguro, 2), sobre el monto inicial.
   * @rule R-011
   * @rule R-010
   */
  monthlyInsurance(principal: Decimal, customerAge: number): Decimal {
    return principal.times(this.rateForAge(customerAge)).setScale(MONEY_SCALE, 'HALF_UP');
  }
}

import { Decimal } from '../../shared/decimal.ts';

export class LoanTotalsCalculator {
  /**
   * Interés total = cuota * plazo - principal (exacto, sin ROUNDED, sin seguro).
   * @rule R-012
   */
  totalInterest(monthlyPayment: Decimal, termMonths: number, principal: Decimal): Decimal {
    return monthlyPayment.times(Decimal.of(termMonths)).minus(principal);
  }

  /**
   * Total pagado = (cuota + seguro) * plazo (exacto, sin ROUNDED).
   * @rule R-013
   */
  totalPaid(monthlyPayment: Decimal, insurance: Decimal, termMonths: number): Decimal {
    return monthlyPayment.plus(insurance).times(Decimal.of(termMonths));
  }
}

import type { LoanRequest } from './LoanRequest.ts';
import { LoanOutcome } from './LoanOutcome.ts';
import type { EligibilityPolicy } from './EligibilityPolicy.ts';
import type { AnnualRateCalculator } from './pricing/AnnualRateCalculator.ts';
import type { AmortizationCalculator } from './pricing/AmortizationCalculator.ts';
import type { InsuranceCalculator } from './pricing/InsuranceCalculator.ts';
import type { LoanTotalsCalculator } from './pricing/LoanTotalsCalculator.ts';

export interface LoanDecisionDependencies {
  readonly eligibility: EligibilityPolicy;
  readonly annualRates: AnnualRateCalculator;
  readonly amortization: AmortizationCalculator;
  readonly insurance: InsuranceCalculator;
  readonly totals: LoanTotalsCalculator;
}

/**
 * Servicio de dominio que decide aprobación o rechazo y calcula los importes.
 */
export class LoanDecisionService {
  private readonly deps: LoanDecisionDependencies;

  constructor(deps: LoanDecisionDependencies) {
    this.deps = deps;
  }

  /**
   * Si hay rechazo no se calcula nada más; si no, se aprueba con código en blanco.
   * @rule R-014
   */
  decide(request: LoanRequest): LoanOutcome {
    const rejection = this.deps.eligibility.firstRejection(request);
    if (rejection !== null) {
      return LoanOutcome.rejected(rejection);
    }
    return this.approve(request);
  }

  /**
   * Ejecuta R-005 a R-013 para una solicitud elegible.
   * @rule R-005
   * @rule R-006
   * @rule R-007
   * @rule R-008
   * @rule R-009
   * @rule R-010
   * @rule R-011
   * @rule R-012
   * @rule R-013
   * @rule R-014
   */
  private approve(request: LoanRequest): LoanOutcome {
    const { annualRates, amortization, insurance, totals } = this.deps;
    const annualRate = annualRates.calculate(request);
    const monthlyRate = amortization.monthlyRate(annualRate);
    const factor = amortization.capitalizationFactor(monthlyRate, request.termMonths);
    const monthlyPayment = amortization.monthlyPayment(request.principal, monthlyRate, factor);
    const monthlyInsurance = insurance.monthlyInsurance(request.principal, request.customerAge);
    return LoanOutcome.approved({
      annualRate,
      monthlyPayment,
      insurance: monthlyInsurance,
      totalInterest: totals.totalInterest(monthlyPayment, request.termMonths, request.principal),
      totalPaid: totals.totalPaid(monthlyPayment, monthlyInsurance, request.termMonths),
    });
  }
}

import type { LoanRequest } from '../../domain/loan/LoanRequest.ts';
import type { LoanOutcome } from '../../domain/loan/LoanOutcome.ts';

/**
 * Puerto de entrada: evaluar una solicitud de préstamo.
 */
export interface EvaluateLoanPort {
  execute(request: LoanRequest): LoanOutcome;
}

export interface AuditEntry {
  readonly status: string;
  readonly errorCode: string;
}

/**
 * Puerto de salida: auditoría del resultado (sin datos personales).
 */
export interface AuditLogPort {
  record(entry: AuditEntry): void;
}

import type { LoanRequest } from '../domain/loan/LoanRequest.ts';
import type { LoanOutcome } from '../domain/loan/LoanOutcome.ts';
import type { LoanDecisionService } from '../domain/loan/LoanDecisionService.ts';
import type { EvaluateLoanPort } from './ports/EvaluateLoanPort.ts';
import type { AuditLogPort } from './ports/AuditLogPort.ts';

/**
 * Caso de uso: evalúa la solicitud con el dominio y audita el resultado.
 */
export class EvaluateLoanUseCase implements EvaluateLoanPort {
  private readonly decisionService: LoanDecisionService;
  private readonly auditLog: AuditLogPort;

  constructor(decisionService: LoanDecisionService, auditLog: AuditLogPort) {
    this.decisionService = decisionService;
    this.auditLog = auditLog;
  }

  execute(request: LoanRequest): LoanOutcome {
    const outcome = this.decisionService.decide(request);
    this.auditLog.record({ status: outcome.status, errorCode: outcome.errorCode });
    return outcome;
  }
}

import type { AuditEntry, AuditLogPort } from '../application/ports/AuditLogPort.ts';

/**
 * Adaptador de salida simulado: guarda las entradas en memoria.
 */
export class InMemoryAuditLog implements AuditLogPort {
  private readonly entries: AuditEntry[] = [];

  record(entry: AuditEntry): void {
    this.entries.push(entry);
  }

  all(): readonly AuditEntry[] {
    return this.entries;
  }
}

import { Decimal } from '../domain/shared/decimal.ts';
import { LoanRequest } from '../domain/loan/LoanRequest.ts';
import type { LoanOutcome } from '../domain/loan/LoanOutcome.ts';

const PRINCIPAL_PATTERN = /^-?\d{1,9}(\.\d{1,2})?$/;
const INTEGER_PATTERN = /^\d{1,3}$/;

export class InvalidInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InvalidInputError';
  }
}

/**
 * Adaptador de entrada/salida: traduce cadenas a tipos de dominio y viceversa.
 */
export class StringLoanMapper {
  toRequest(input: Record<string, string>): LoanRequest {
    return new LoanRequest(
      this.parsePrincipal(input['principal']),
      this.parseInteger('term_months', input['term_months']),
      this.parseInteger('credit_score', input['credit_score']),
      this.parseInteger('customer_age', input['customer_age']),
    );
  }

  toOutput(outcome: LoanOutcome): Record<string, string> {
    return {
      status: outcome.status,
      error_code: outcome.errorCode,
      annual_rate: outcome.annualRate.toString(),
      monthly_payment: outcome.monthlyPayment.toString(),
      insurance: outcome.insurance.toString(),
      total_interest: outcome.totalInterest.toString(),
      total_paid: outcome.totalPaid.toString(),
    };
  }

  private parsePrincipal(raw: string | undefined): Decimal {
    const text = (raw ?? '').trim();
    if (!PRINCIPAL_PATTERN.test(text)) {
      throw new InvalidInputError('principal inválido');
    }
    return Decimal.of(text).setScale(2, 'DOWN');
  }

  private parseInteger(name: string, raw: string | undefined): number {
    const text = (raw ?? '').trim();
    if (!INTEGER_PATTERN.test(text)) {
      throw new InvalidInputError(name + ' inválido');
    }
    return Decimal.of(text).toInteger();
  }
}

import { EvaluateLoanUseCase } from './application/EvaluateLoanUseCase.ts';
import { LoanDecisionService } from './domain/loan/LoanDecisionService.ts';
import { EligibilityPolicy } from './domain/loan/EligibilityPolicy.ts';
import { AmountRangeRule } from './domain/loan/rules/AmountRangeRule.ts';
import { TermRangeRule } from './domain/loan/rules/TermRangeRule.ts';
import { MaturityAgeRule } from './domain/loan/rules/MaturityAgeRule.ts';
import { MinimumScoreRule } from './domain/loan/rules/MinimumScoreRule.ts';
import { BaseRateTable } from './domain/loan/pricing/BaseRateTable.ts';
import { AnnualRateCalculator } from './domain/loan/pricing/AnnualRateCalculator.ts';
import { HighScoreShortTermPromotion } from './domain/loan/pricing/HighScoreShortTermPromotion.ts';
import { LongTermSurcharge } from './domain/loan/pricing/LongTermSurcharge.ts';
import { AmortizationCalculator } from './domain/loan/pricing/AmortizationCalculator.ts';
import { InsuranceCalculator } from './domain/loan/pricing/InsuranceCalculator.ts';
import { LoanTotalsCalculator } from './domain/loan/pricing/LoanTotalsCalculator.ts';
import { InMemoryAuditLog } from './infrastructure/InMemoryAuditLog.ts';
import { StringLoanMapper } from './infrastructure/StringLoanMapper.ts';

function buildUseCase(): EvaluateLoanUseCase {
  const table = new BaseRateTable();
  const eligibility = new EligibilityPolicy([
    new AmountRangeRule(),
    new TermRangeRule(),
    new MaturityAgeRule(),
    new MinimumScoreRule(table),
  ]);
  const decisionService = new LoanDecisionService({
    eligibility,
    annualRates: new AnnualRateCalculator(table, [new HighScoreShortTermPromotion(), new LongTermSurcharge()]),
    amortization: new AmortizationCalculator(),
    insurance: new InsuranceCalculator(),
    totals: new LoanTotalsCalculator(),
  });
  return new EvaluateLoanUseCase(decisionService, new InMemoryAuditLog());
}

/**
 * Punto de entrada: recibe y devuelve todos los valores como cadenas.
 */
export function execute(input: Record<string, string>): Record<string, string> {
  const mapper = new StringLoanMapper();
  const outcome = buildUseCase().execute(mapper.toRequest(input));
  return mapper.toOutput(outcome);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/index.ts';

const base = { principal: '10000.00', term_months: '12', credit_score: '800', customer_age: '30' };

test('rechaza monto fuera de rango con E01 y valores en cero', () => {
  const out = execute({ ...base, principal: '999.99' });
  assert.equal(out['status'], 'REJECTED');
  assert.equal(out['error_code'], 'E01');
  assert.equal(out['annual_rate'], '0.0000');
  assert.equal(out['monthly_payment'], '0.00');
});

test('E02 tiene prioridad sobre E03 y E04', () => {
  const out = execute({ ...base, term_months: '5', customer_age: '80', credit_score: '300' });
  assert.equal(out['error_code'], 'E02');
});

test('rechaza edad al vencimiento mayor a 75 con E03', () => {
  const out = execute({ ...base, term_months: '132', customer_age: '65' });
  assert.equal(out['error_code'], 'E03');
});

test('rechaza puntaje menor a 550 con E04', () => {
  const out = execute({ ...base, credit_score: '549' });
  assert.equal(out['error_code'], 'E04');
});

test('aprueba aplicando promoción R-005 y seguro R-011', () => {
  const out = execute(base);
  assert.equal(out['status'], 'APPROVED');
  assert.equal(out['error_code'], '');
  assert.equal(out['annual_rate'], '0.0874');
  assert.equal(out['insurance'], '3.50');
});
